const fs = require('fs'), crypto = require('crypto');
const root='F:/EQ1/Bastion_Dev/quests/';
const decisions=JSON.parse(fs.readFileSync('docs/encounter-audit/saved-decisions.json')).rows;
const candidates=JSON.parse(fs.readFileSync('docs/encounter-audit/encounter-candidates.json')).rows;
const output=[]; const entries=[];
const zones={acrylia:'Acrylia Caverns',akheva:'Akheva Ruins',anguish:'Anguish, the Fallen Palace',arena2:'The Arena',barindu:'Barindu, Hanging Gardens',bloodfields:'The Bloodfields',cauldron:'Dagnor\'s Cauldron',causeway:'Nobles\' Causeway',cazicthule:'Temple of Cazic-Thule',chambersa:'Muramite Proving Grounds',chambersb:'Muramite Proving Grounds',chambersc:'Muramite Proving Grounds',chambersd:'Muramite Proving Grounds',chamberse:'Muramite Proving Grounds',chambersf:'Muramite Proving Grounds',chardokb:'Chardok: Halls of Betrayal',citymist:'City of Mist',cobaltscar:'Cobalt Scar',codecay:'Ruins of Lxanvom',corathus:'Corathus Creep',corathusb:'Corathus Lair',dawnshroud:'Dawnshroud Peaks',delvea:'Lavaspinner\'s Lair',delveb:'Tirranun\'s Delve',drachnidhive:'The Hive',drachnidhivea:'The Hatchery',drachnidhivec:'Queen Sendaii\'s Lair',dragonscalea:'Dragonscale Hills',dranik:'Ruined City of Dranik',draniksscar:'Dranik\'s Scar',dreadlands:'Dreadlands',dreadspire:'Dreadspire Keep',dulak:'Dulak\'s Harbor',eastkarana:'Eastern Plains of Karana',eastkorlach:'The Undershore',eastkorlacha:'Snarlstone Dens',eastwastes:'Eastern Wastes',emeraldjungle:'The Emerald Jungle',fearplane:'Plane of Fear',feerrott:'The Feerrott',ferubi:'Ferubi, Forgotten Temple of Taelosia',fieldofbone:'The Field of Bone',freportw:'West Freeport',frontiermtns:'Frontier Mountains',fungusgrove:'Fungus Grove',gfaydark:'Greater Faydark',greatdivide:'The Great Divide',grimling:'Grimling Forest',growthplane:'Plane of Growth',guke:'Deepest Guk: The Cauldron of Lost Souls',gukg:'Deepest Guk: The Root Garden'};
function add(n,summary,tips,opt={}){const id=typeof n==='number'?'E'+String(n).padStart(3,'0'):n;entries.push({id,summary,tips,...opt});}
function phase(label,trigger,description){return{id:label.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),label,trigger,description};}
function generate(){for(const e of entries){let r=decisions.find(x=>x.id===e.id),c=candidates.find(x=>x.id===e.id);if(!r||r.decision!=='A')throw new Error('Not approved '+e.id);let paths=e.files||[...new Set(c.sources.map(s=>s.path))];paths=[...new Set(paths.concat(e.extraFiles||[]))];let texts=paths.map(p=>fs.readFileSync(root+p,'utf8'));let npc=e.npc||[...new Set(texts.flatMap(s=>[...s.matchAll(/eq\.register_npc_event\([^\n]*?Event\.(?:combat|hp|death_complete),\s*(\d+)/g)].map(m=>+m[1])))];let issues=[...(e.issues||[])];if(!npc.length)issues.push('Primary NPC template ID remains unverified; npc_ids is intentionally empty.');let title=e.title||r.title,slug=(r.zone+'-'+(e.slug||title)).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,100);let doc={schema_version:1,slug,title,group:e.group||r.series,type:e.type||(['raid','group','event'].includes(r.type)?r.type:'group'),zone:{short_name:r.zone,name:zones[r.zone]||r.zone,version:e.version||0},npc_ids:npc,status:'draft',spoiler:false,summary:e.summary,overview:e.overview||[e.summary],roles:e.roles||[],phases:e.phases||[],abilities:e.abilities||[],sections:[{id:'strategy',title:'Encounter strategy',paragraphs:[],bullets:e.tips,items:[]}],loot:e.loot||[],sources:{reviewed_at:'2026-09-29',revision:'f3100d1a539093c717344860d4499558c48c7453',verification:'source-reviewed',files:paths.map(p=>({path:p,sha256:crypto.createHash('sha256').update(fs.readFileSync(root+p)).digest('hex')})),notes:['Reviewed quest source; behavior, balance, spawns and completion have not been verified in a live instance.',...(e.version?['This document applies to instance version '+e.version+'.']:['The reviewed source is standard or unversioned; this draft applies to version 0.']),...(e.notes||[]),...issues]}};let path='resources/data/encounters/'+slug+'.json';if(fs.existsSync(path)&&!JSON.parse(fs.readFileSync(path)).sources?.notes?.includes('Reviewed quest source; behavior, balance, spawns and completion have not been verified in a live instance.'))throw new Error('Refusing overwrite '+path);fs.writeFileSync(path,JSON.stringify(doc,null,2)+'\n');output.push({id:e.id,slug,issues});}fs.writeFileSync('docs/encounter-audit/generated-a.json',JSON.stringify(output,null,2)+'\n');console.log(JSON.stringify({documents:output.length,ids:new Set(output.map(r=>r.id)).size}));}
add(1,'Survive the grimling waves to draw out Archmage Gorraferg.', ['Assemble before triggering the ring; the controller advances through eight wave stages.','Pick up new grimlings promptly and keep the fighting area clear for the next wave.','The last stage calls the archmage after a short delay. Save resources for that final opponent.'],{npc:[154388]});
add(3,'A sustained wave event ends with High Priest Gakkernog.', ['Remain near the event trigger while clearing the waves.','The wave sequence includes pauses and changes in the enemies summoned. Use those breaks to recover.','Engage the high priest promptly when he appears; his unengaged appearance is temporary.']);
add(4,'Break the warder and arcanist defenses before facing Khati Sha.', ['Complete the warder and chanting sequence; Khati Sha is the final stage of the event.','Clear the disruptive minions and distinguish the false arcanist from the true arcanists.','Defeat the death guards before progressing the arcanist stage.','Keep Khati Sha in his encounter area and be ready to control returning guards.'],{notes:['The prerequisite scripts contain timed failure conditions; live timing and spawn wiring remain unverified.']});
add(5,'Fight through successive grimling rounds in the Ring of Fire.', ['Prepare for repeated trash waves followed by stronger enemies.','Keep tanks available for the named boss at the end of each round.','Use gaps between spawns to recover and reposition before the next round.']);
add(6,'Escort Trondol Shir through a guarded escape route.', ['Have the group ready before the quest hand-in starts the escort.','Clear the three guards and soulstealer promptly; the room-clear stage has a five-minute limit.','Stay with Trondol until his final stop and complete the follow-up hand-in promptly.']);
add(9,'Shei Vinitras replaces his decoy with a raid encounter that punishes deaths.', ['Expect the apparent Shei to give way to the real boss.','Assign a plan for Death Touch and keep the raid stable; player and pet deaths can generate more enemies.','Pick up the summoned adds quickly so one death does not become a chain of losses.']);
add(10,'The Insanity Crawler summons mind worms when it kills a player or pet.', ['Keep players and pets alive to limit the number of mind worms.','Have an add tank ready to collect four worms when a kill triggers them.','The crawler has a limited appearance window, so assemble before engaging.'],{title:'The Insanity Crawler',group:'Akheva',npc:[179350],files:['akheva/The_Insanity_Crawler.lua','akheva/insanity.lua']});
add(10,'The seasonal crawler combines silence, piercing vulnerability and death-triggered worms.', ['Control mind worms immediately when a player or pet death brings them into the fight.','Prepare for silence at 50% health and recurring screeches throughout combat.','At 20% health the crawler becomes more vulnerable to piercing attacks.','An out-of-combat reset clears the worms and restores the damage modifiers.'],{title:'Time-Corrupted Insanity Crawler',version:200,npc:[179000],files:['akheva/A_Time-Corrupted_Insanity_Crawler.lua','akheva/insanity.lua'],notes:['The tremor timer produces flavor text; no separate tremor damage mechanic is documented.']});
add(11,'Arch Magus Vangl combines shifting focus with dangerous recurring converts.', ['Pick up languished converts quickly and kill them before their increasing strength becomes overwhelming.','Watch the focus and mark announcements while maintaining boss control.','Prepare for additional pressure as Vangl crosses his health stages.']);
add(12,'Free Jelvan by defeating his three linked tormentors with balanced damage.', ['Assign a tank and healing coverage to each tormentor.','Keep their health close together; the encounter checks their relative progress repeatedly.','Coordinate damage swaps and use Jelvan\'s blessings while keeping every group alive.','Pulling a tormentor beyond the arena or leaving the event idle can reset it.']);
add(13,'Keldovan becomes easier to handle when the raid keeps killing his pit adds.', ['Assign a group to the pit fiends and hounds while the main tank holds Keldovan.','Recent add kills weaken the boss, but that advantage decays if kills stop.','Keep healing and curse handling organized through his recurring combat spell rotation.'],{npc:[317005,317102,317103]});
add(14,'Overlord Mata Muram tests gaze reactions and add control through several health stages.', ['When warned that the gaze is focusing on you, obtain Reflective Skin before the ten-second warning ends.','Pick up the additional enemies at the health transitions while keeping healing coverage on the boss tank.','Prepare for the banishment and lieutenant stage near the end of the fight, then reassemble for the finish.'],{npc:[317109],abilities:[{id:'gaze',name:'Mata Muram\'s Gaze',summary:'A selected player has ten seconds to prepare Reflective Skin.',description:['The script checks the selected player for Reflective Skin when the warning expires.'],tags:['Personal responsibility'],roles:[],spell_ids:[5685,6494]}]});
add(15,'Ture alternates heavy attacks with a clearly announced area rampage.', ['Melee should move out when the rampage warning begins.','The warning gives six seconds before a ten-second area-rampage window. Return after it ends.','Keep the tank covered through recurring breath and destruction casts.'],{npc:[317003]});
add(16,'Warden Hanvar\'s guards control how far the raid can lower his health.', ['Kill the guards to lower Hanvar\'s protected health floor.','Finish each guard set promptly; guards have their own disappearance timer.','Keep boss control and healing stable while damage dealers switch to the guards.'],{npc:[317002]});
add(17,'Follow the safe floor wedges while managing fever and mana burn.', ['During combat, cure Decrepit Fever with disease cures.','Pure casters should leave the purple mana-burn radius and use the refuge when warned.','During the dance, follow the safe wedge as it travels across the floor and back. Warnings shorten on later dances.','Combat lasts 90 seconds and each dance lasts 45 seconds.'],{version:6,npc:[180002],notes:['Ground markers require compatible telegraph support; geometry and client display have not been live-verified.']});
add(18,'Defeat the Avatar quickly while matching each defense and destroying despair adds.', ['Match the announced spell school or weapon style as the Avatar changes defenses.','Stand inside a green rune for two seconds to gain twenty seconds of attunement when your usual attacks are unsuitable.','Destroy each trio of despair manifestations within 45 seconds.','The final quarter of the Avatar\'s health opens every attack type again.'],{version:7,npc:[180004,180005,180006,180007],phases:[phase('Open defenses','100% to 75%','Every spell and weapon is effective.'),phase('Changing defenses','75% to 25%','In order: cold and hand-to-hand; magic and piercing; poison and slashing; disease and blunt; fire and two-handed weapons.'),phase('Final assault','Below 25%','All attack types become effective again.')]});
for(const [version,label,warn,hold] of [[2,'Simple',6.5,3],[3,'Moderate',5.5,3.5],[4,'Difficult',4.5,4],[5,'Insane',3.5,4.5]])add(19,'A cooperative movement trial with four health locks and '+label.toLowerCase()+' difficulty.', ['Bring at least three players and respond to the floor markers together.','This difficulty gives '+warn+' seconds for ordinary hazard warnings.','At 80%, occupy all three seals and hold them for '+hold+' seconds.','At 60%, dodge the sweeping fields, then gather three players in the blue rally circle.','At 40%, divide the group between the two violet circles and keep both sides balanced.','At 20%, survive the final patterns. A failed trial causes a short empowered attack window before the trial repeats.'],{title:'Trial of the Dreadscale: '+label,version,npc:[180002],notes:['Training encounter grants no loot or replay lockout. Ground geometry and client marker presentation remain unverified in game.']});
add(20,'Break the controllers\' formation to face the Colossus of War and Ixvet Pox.', ['Plan for the constructs to activate when their controllers enter combat.','The poison quest sequence can disrupt the controllers; complete its setup before starting combat if using that route.','Keep a tank ready for the colossus when controller deaths release it.','Stay within the encounter area and finish Ixvet to complete the linked sequence.'],{notes:['The source explicitly marks the post-Ixvet Nihil uprising behavior as incompletely parsed.']});
add(21,'Kyv Rux Vhedt changes to a ranged attack pattern at low health.', ['Expect the ranged behavior to begin at 45% health.','Keep the group ready for volleys as the casting timer repeats.','Maintain tank control while closing out the encounter.']);
add(22,'A beastlord epic encounter opens with six savage ferans.', ['Assemble before the boss appears; its appearance lasts thirty minutes.','Assign control for the six ferans immediately on spawn.','Keep the boss tank covered while the group reduces the add pressure.']);
add(23,'Chase Jekisia through the caverns while handling her repeated reinforcements.', ['At successive health thresholds, Jekisia relocates and calls pairs of dragorn flunkies.','Clear or control the flunkies before the group follows her to the next position.','Keep moving through the stages; the encounter has a twenty-minute reset timer.','Remaining flunkies are not automatically removed by the boss\'s death.']);
add(24,'Wake Gazz by defeating the dreamwalkers, then adapt to his alternating combat modes.', ['Defeat the three dreamwalkers and prepare for Gazz to awaken.','When Gazz slows and flails, keep vulnerable players clear of the area-rampage pressure.','His later roar leads into Reflective Sheen; watch the change before committing spells.','A prolonged disengagement starts the event reset sequence.'],{npc:[301031,301062]});
add(25,'Kragsmash calls strength and speed adds at three health thresholds.', ['The eligible monk starts the challenge through dialogue.','At 75%, 50% and 25%, collect the paired strength and speed adds.','Keep enough damage and healing available to finish inside the thirty-minute combat window.']);
add(26,'Defeat Marshal Histent and subdue Grinbik to free him from control.', ['Handle the marshal and his supporting enemies without losing control of Grinbik.','Lower Grinbik to 10% and allow the surrender check to complete.','The eligible ranger should hail the freed Grinbik to finish the rescue.'],{notes:['Grinbik arms a timer named Depop but checks depop in its handler; reliable cleanup timing needs a live check.']});
add(27,'A chain of reclusive girplans leads to a quest-dependent named opponent.', ['Defeat each emerging girplan to bring out the next one.','Tanks should regain threat after the recurring knockback and hate wipe.','Each stage has a 930-second appearance timer; keep the chain moving.','The final branch produces Rolthee or Myrhee according to quest state.'],{npc:[301033,301073,301076,301077,301079]});
add(28,'The Keeper accepts a monk\'s epic challenge for a limited time.', ['The eligible monk must start the challenge through dialogue.','Defeat the Keeper within the thirty-minute combat window.','Maintain steady tanking and healing through his health-based taunts.'],{notes:['The 65% and 35% handlers contain dialogue only; no additional phase mechanics are claimed.']});
add(29,'Clear Kaavi\'s defenders before confronting the war caller.', ['Defeat the sentries and guardians that prevent Kaavi from being attacked.','Keep add control available when the boss becomes vulnerable.','At 90% health, Kaavi\'s NPC script summons two additional sentinels.'],{npc:[301042,301017,301043,301086],issues:['The encounter module registers War_Combat although its definition is commented out. Loader behavior and overlap with the NPC script need live verification.']});
add(33,'Praklion retreats twice before the quest fight can be completed.', ['At 70% and 30%, Praklion wipes threat and moves to a new location.','Follow the retreat and wait for the brief immunity to end before rebuilding threat.','Allow both retreats to happen; the second stage enables the quest-specific drop.']);
add(34,'Alpha Feran calls other ferans into the fight.', ['Expect the first call ten seconds after engagement and further calls every fifteen seconds.','Control nearby ferans before committing to the boss.','Have a tank collect any ferans brought into combat by the howl.']);
add(35,'Bazu Smasher repeatedly calls pairs of hulks as its health falls.', ['Plan for two hulks at each of 90%, 75%, 70%, 55%, 50%, 35%, 30%, 15% and 10%.','Control damage near adjacent thresholds so the group can collect each pair.','An extended disengagement clears the summoned hulks.'],{npc:[303081,303106]});
add(36,'Defeat Bazu Terror and its crushers to expose the dark animist.', ['The eligible beastlord starts the event through Jillaa Oogblat.','Be ready for four bazu crushers alongside the boss.','Bazu Terror\'s death summons the dark animist at its position.','The bazu stage has a thirty-minute appearance window.'],{npc:[303092,303093,303094]});
add(37,'Kreljnok calls adds that dramatically increase his regeneration while alive.', ['Collect Kreljnok\'s Power and Kreljnok\'s Rage when they appear.','Prioritize those adds to return the boss\'s regeneration to its lower state.','A new pair is called every 150 seconds during combat; finish before the thirty-minute appearance ends.']);
add(38,'Defeat successive elemental splits to expose the Essence of Air again.', ['The eligible magician activates the encounter by reaching its hidden trigger.','At 80%, 60%, 40%, 20% and 10%, the essence disappears and summons a larger set of lesser essences.','Kill every essence of the current set to make the boss return.','Tanks should rebuild threat after each return; complete the sequence inside thirty minutes.'],{npc:[303100,303101,303102,303103,303104,303105]});
add(39,'Oshiruk repeatedly casts Tendrils during the bard epic finale.', ['Keep the tank and nearby group covered for a Tendrils cast every twelve seconds.','Recover between casts while maintaining steady damage.'],{abilities:[{id:'tendrils',name:'Tendrils of Oshiruk',summary:'A recurring cast directed at the current target.',description:[],tags:['Recurring spell'],roles:[],spell_ids:[5975]}]});
add(40,'Subdue Siflu and speak with him after the Muramite control breaks.', ['Lower Siflu to 15% health rather than expecting a death completion.','Once he becomes immune and stops fighting, the eligible ranger should follow the adventurers dialogue.','Complete the encounter and dialogue before his fifteen-minute appearance ends.']);
add(41,'Menlo repeatedly forces refugee groups into battle.', ['Keep a tank available for refugees while the main tank holds Menlo.','A new refugee group is called every minute, cycling through five groups.','Idle refugees can be drawn into the fight between calls, so watch the whole area.']);
add(42,'The seasonal Stone Thrower pressures both close and distant players.', ['Watch personal warnings and reposition before their ten-second impact.','For the reviewed rock-blast logic, finish within 100 units of the boss; targets beyond that distance take the hit.','When targeted by the distant-player grip, move within 150 units before it resolves.','Keep the main tank covered for recurring boulder strikes.'],{version:200,issues:['The close-range warning tells players to get away, but the impact condition damages targets farther than 100 units. Guidance follows the implemented condition and needs live verification.','A final_fury timer is armed but no handler was found; no timed enrage is claimed.']});
add(43,'Withering Murkglider releases parasites repeatedly as its health falls.', ['Expect three parasitic murkgliders at 99%, 79%, 59%, 39% and 19%.','Control the parasites before pushing through another threshold.','A disengagement fully heals the boss and rearms the sequence.']);
add(44,'Protect Gimlik while he studies the temple and survives its ambushes.', ['Tell Gimlik you are ready only when the group can stay with him.','Collect the attackers at each of his research stops.','Defeat the tracker near the end and complete Gimlik\'s requested follow-up before leaving.']);
add(45,'Interrupt the sacrifice, survive the temple waves and face the avatars of fear.', ['Engaging the high priest draws his guards into combat.','After the priest falls, the linked sequence escalates through waves and the Avatars of Dread, Fright and Terror.','Keep resources for the Avatar of Fear when the final stage becomes attackable.','Finish the final avatar within its thirty-minute window.'],{npc:[48384,48385,48386]});
add(46,'Weaken the sickly mosquito for the quest interaction and prepare for its final disease cast.', ['At 25% health a capture check begins every fifteen seconds.','The ranger must have dealt damage and hold the required capture tool in the primary slot; keep the mosquito alive while waiting for the capture check.','If the mosquito dies, it casts Epidermal Rot on a random hated target.']);
add(47,'Use fear to control susceptible enemies while defeating the fearless attackers.', ['Begin only when everyone is ready for the fifteen-minute trial.','Keep fear on susceptible enemies; the script drains their health while they are feared.','Defeat at least fifteen of the fearless enemies before the timer expires.'],{version:1});
add(48,'Clear the ferans, then rotate tanks to control the Master of Hate\'s growing damage.', ['Kill the feran mothers while controlling the direpups they produce.','When the master activates, rotate the top-threat tank deliberately.','His maximum hit rises while one tank remains on top; a detected tank change resets that escalation.'],{version:2});
add(49,'Survive a twenty-minute assault with coordinated control and sustained healing.', ['Prepare for a survival fight rather than a quick boss burn.','Collect each new wave and use crowd control to keep the number of active attackers manageable.','Conserve mana and rotate defensive abilities so the raid can survive the full twenty minutes.'],{version:2});
add(50,'Defeat four opponents by adapting your weapons to their vulnerabilities.', ['Use slashing against the Hulking Bazu.','Use piercing, backstab or archery against Hemkai the Ascendant.','Use blunt or hand-to-hand attacks against the Granite Stoneguardian.','Steelshock strongly reduces most weapon damage; reserve spell damage for this opponent.'],{version:1,npc:[305000,305001,305002,305003]});
add(51,'Follow personal and raid warnings to survive the Trial of Foresight.', ['Move to the announced safe side when the room heats up.','Read your kyv warning carefully: it may require moving, standing still or ducking.','Remove the specified rings or main-hand weapon when the equipment warning appears.','Watch dragorn preparations and respond with distance or focused damage as the warning directs.'],{version:2});
add(52,'Recover enough seals to challenge the Master of Subversion.', ['Collect seals until their combined value reaches 300 points.','Copper, silver and gold seals contribute 10, 20 and 30 points respectively.','Avoid unnecessary fighting while gathering, then prepare to defeat the master when the required total is reached.'],{version:1});
add(53,'Clear timed waves while fighting under the Test of Efficiency debuff.', ['Expect the trial debuff to be maintained throughout the encounter.','Use resources carefully and finish the active enemies before later waves arrive.','Complete the wave sequence within the fifteen-minute trial.'],{version:1});
add(54,'The Master of Specialization cycles through spells that test the raid\'s adaptability.', ['Prepare for a new spell in the scripted rotation every twenty-five seconds.','Adjust damage and support as each effect changes which tools are effective.','Maintain tank healing throughout the alternating weakening and damaging casts.'],{version:2,abilities:[{id:'spell-cycle',name:'Specialization spell cycle',summary:'A repeating sequence of eight spells.',description:['Imprecision, Searing Pain, Rigidity, Chilling Agony, Curse of Misfortune, Glimmering Aura, Impurity and Toxic Blast are cast in order.'],tags:['Adaptation'],roles:[],spell_ids:[5700,5723,5701,5724,5702,5725,5703,5726]}]});
add(55,'Adapt to constructs whose changing forms alter resistances and combat abilities.', ['Identify the active form before committing your strongest attacks.','Favor cold against the fire form and fire against the ice form.','Keep extra healing available for the forms with rampage or flurry.','Pick up supporting constructs as they appear and adjust weapon choices to the current form.'],{version:2});
add(56,'Defeat the Master of Ingenuity while reflection and pet pressure limit easy damage.', ['Watch for Reflective Sheen every forty-five seconds before casting into the master.','Damage shields are repeatedly removed from players on the hate list.','Pets on the hate list are hit by a heavy attack every three minutes.','Finish the master within the fifteen-minute trial.'],{version:1});
add(57,'Defeat increasingly large groups of adventurer-like opponents.', ['The three waves grow from a small balanced party to a much larger force.','Assign control for healers and dangerous casters while tanks collect the melee enemies.','Expect class-specific tricks, including monk recovery and wizard positioning behavior.','Keep the fighting inside the trial area.'],{version:2,notes:['Opponent identities are selected from class-specific source tables; NPC links include only literal registered participants.']});
add(58,'Defeat enough attackers to expose the Master of Destruction, then finish him.', ['Kill twenty of the trial enemies to activate the master.','Keep the group moving from target to target so the initial enemies do not consume the time budget.','Save enough resources for the master; the entire trial lasts fifteen minutes.'],{version:1});
add(59,'Korucust pairs recurring spell attacks with a transformation at 40% health.', ['Prepare for Cloud of Oblivion ten seconds after the pull, then once each minute.','Korucust\'s Vengeance follows the cloud by two seconds.','At 40%, Korucust casts Phantasmal Shift. Keep tank control through the transition.'],{abilities:[{id:'cloud-sequence',name:'Cloud and Vengeance',summary:'Two linked casts pressure the current tank.',description:[],tags:['Tank pressure'],roles:[],spell_ids:[3852,4015]},{id:'shift',name:'Phantasmal Shift',summary:'Korucust transforms at 40% health.',description:[],tags:['Health phase'],roles:[],spell_ids:[4013]}]});
add(60,'Weaken the leprous chokidai to complete its ranger quest interaction.', ['Lower the chokidai to 25% to begin the capture checks.','The ranger must have dealt damage and hold the required capture tool in the primary slot; keep the chokidai alive while waiting for capture.','A death triggers Epidermal Rot against a random hated target.']);
add(61,'Black reavers can continue into replacement enemies and named opponents.', ['Keep a tank ready at the death location because a replacement may appear immediately.','The normal reaver chain can produce a shadow, Ghiosk or another reaver. Clearing the last normal reaver can call Rak\'Ashiir.','A separate reaver script chooses normal or fabled named opponents from the active content flag.'],{npc:[90005,90193,90194,90200,90201,90011,90012],notes:['The fabled branch is controlled by fabled_kunark, not an independently verified instance version. Both source branches are covered in this version-0 draft.']});
add(62,'A shaman quest summons a dangerous shark and two companions beneath Cobalt Scar.', ['Have underwater travel and combat preparations ready before speaking with Yoppa.','The eligible shaman starts the encounter through the quest dialogue.','Collect all three sharks and focus the group on one target at a time.']);
add(63,'Clear the crypt\'s escalating defenders and kings to summon Bertoxxulous.', ['Assemble before triggering the Spectre of Corruption sequence.','After the opening delay, rooms activate in succession. Control incoming defenders and track the named kings.','Clear the required enemies to bring out Bertoxxulous, preserving resources for the final fight.','The full event has a two-hour failure timer.'],{npc:[200260,200238,200244,200255,200247,200251,200254,200256,200233,200248,200250,200249,200235]});
add(64,'Break Carprin\'s guard protection and follow the named sequence deeper into the crypt.', ['Defeat all three guards before killing Carprin; killing him first brings out a replacement with another guard set.','Rebuild threat after Carprin\'s recurring hate wipes.','Prevent deaths during Avhi Escron: fallen players cause more reanimated reavers to appear.','Prepare for each named successor and its accompanying enemies before advancing.'],{notes:['The draft covers the linked stages present in the reviewed Carprin, Avhi and Bishop scripts; database combat spell lists were not reviewed.']});
add(65,'Defeat Banord\'s puslings and subsequent waves to draw out the overlord.', ['Clear the initial puslings to start the timed wave progression.','Hold the room through the minion waves and prepare for Banord to become attackable.','Avoid leaving the final boss idle for an extended period, which can reset the event.'],{npc:[200259]});
add(66,'Clear the reapers, then stop their repair support when Taskmaster XVII activates.', ['Defeat all four active creep reapers to summon the Taskmaster.','At 75%, the Taskmaster begins its repair sequence and activates further reapers.','Destroy active repair adds promptly to reduce the boss\'s regeneration.'],{npc:[365290,365246,365243]});
add(67,'Search the mines for Fibblebrap\'s gem and deal with Creeper Clicktok.', ['Follow the mission objectives through the mine and collect the required quest material.','Bring the requested larva material before hailing Clicktok to use the peaceful route.','Hailing Clicktok without the material starts a delayed hostile response.','Complete the pickup and loot objectives before returning through the mission route.'],{version:1,extraFiles:['lua_modules/constants/instance_versions.lua']});
add(68,'Defeat the summoned beasts and their successors for the Hunter\'s Pike quest.', ['The quest hand-in to Carre Harger brings out two initial beasts.','Each initial beast produces a successor on death; keep the group ready for the next target.','Complete both branches before returning with the required quest proof.']);
add(69,'Clear the chest guards and open the treasures in the correct order.', ['Inspect the chests and clear their guards before committing to an opening.','The required opening order is gold, cracked, gilded, then silver.','Opening a later chest while an earlier one remains triggers Meddler\'s Misfortune and ends the mission.'],{version:2,npc:[341103,341102,341101,341100],extraFiles:['lua_modules/constants/instance_versions.lua']});
add(70,'Hunt lavaspinners until the mission eggs appear.', ['Kill lavaspinners to advance the egg-spawn checks.','Watch for the ground-shaking announcement and search for each new egg.','Continue through the cracked eggs to the pristine egg and complete the mission\'s collection objectives.'],{version:8,extraFiles:['lua_modules/constants/instance_versions.lua']});
add(71,'Stonemaw enters combat with three supporting enemies.', ['Prepare to collect Magma, Molten and Smolder when Stonemaw is engaged.','Keep the boss tank covered while the group reduces the three-add pressure.','An out-of-combat timer removes the summoned support after an extended break.']);
add(72,'Destroy the drake eggs and prepare for the matriarch\'s retaliation.', ['Clear drakes and keep watch for the mission\'s egg progression.','Expect additional drakes as eggs are destroyed.','Destroying the fifteenth egg calls the Drake Matriarch; prepare the group before breaking the last egg.'],{version:5,extraFiles:['lua_modules/constants/instance_versions.lua']});
add(73,'Volkara drops egg sacs at health thresholds that soon hatch into spiderlings.', ['At 80%, 60%, 40%, 20% and 10%, expect a new egg sequence.','Deal with egg sacs before their thirty-second hatch timer when possible.','Keep an add tank ready for magma spiderlings and avoid pushing several thresholds together.'],{version:9,npc:[341063,341064],extraFiles:['lua_modules/constants/instance_versions.lua']});
add(74,'Escort the goblins in order and confront the boss at the end of the route.', ['Speak to Higglin and follow the mission dialogue stages in order.','Stay close to the currently moving goblin and clear enemies along its route.','Wait for each escort to arrive before trying the next conversation.','The final boss becomes hostile through dialogue, so regroup before speaking.'],{version:2,npc:[342133,342137,342134,342135,342136,342138],extraFiles:['lua_modules/constants/instance_versions.lua']});
add(75,'Knock out all three mystics together to expose Emoush.', ['Coordinate the mystic kills so their unconscious periods overlap.','Damage Emoush while all three mystics are down.','The mystics revive after three minutes and can restore his protection while increasing his power.','Keep healing available for recurring Rumbling Stone casts.'],{version:4,extraFiles:['lua_modules/constants/instance_versions.lua']});
add(76,'Draw out the Goblin Task Master, then survive his guards.', ['The first thirty qualifying kills advance the alarm sequence.','Find and defeat the Goblin Task Master when the alarm sounds.','His death summons more guards, so keep tanks and healers ready through the aftermath.'],{version:6,npc:[342046],extraFiles:['lua_modules/constants/instance_versions.lua']});
add(77,'Tirranun survives his first defeat and returns in a stronger form.', ['Keep a backup tank ready for banishment of the top-threat target in the opening fight.','The first apparent death begins a recovery period; continue controlling the ash adds.','As Tirranun regenerates, add spawns accelerate before he becomes attackable again.','Spread healing coverage for his recurring area attacks and respect the unstable bridge approach.'],{version:5,extraFiles:['lua_modules/constants/instance_versions.lua'],phases:[phase('Opening fight','Initial engagement','Handle recurring tank banishment.'),phase('Recovery','First apparent defeat','Tirranun becomes protected and regenerates while ash adds appear.'),phase('Renewed assault','Recovery reaches its final threshold','Tirranun returns with increased health and damage, faster adds and further area attacks.')]});
add(78,'Drithnak creates egg sacs during a fight that must stay inside its area.', ['Keep the boss near its encounter position to avoid the out-of-bounds response.','Expect egg sacs on a recurring timer and have someone watch their locations.','Control the resulting pressure while maintaining steady boss damage.'],{issues:['Combat starts a timer named agro but the handler checks aggro; the intended periodic hate-link behavior needs runtime verification.']});
add(79,'Recover the lost notebook while dealing with the Hive\'s traps.', ['Follow the mission\'s enemy and recovery objectives through the Hive.','When a trap engages, prepare for a group of additional drachnids.','Move as a group and recover before triggering another trapped area.'],{version:4,npc:[354266,354264,354252,354273,354258,354253],extraFiles:['lua_modules/constants/instance_versions.lua']});
add(80,'Complete the Hive objectives to confront Foreman Zlixtil.', ['Progress the mission stages before expecting the foreman to become attackable.','Regroup while his dialogue sequence plays.','When the dialogue ends, take control of the foreman and finish the recovery objective.'],{version:1,extraFiles:['lua_modules/constants/instance_versions.lua']});
add(81,'Break cocoons and lead the rescued gnomes to safety.', ['Clear a safe route before opening more cocoons.','Tell a freed gnome to follow and remain close while escorting it to the rescue area.','Use the stop dialogue when the group needs to clear ahead.','Some rescued gnomes develop a dangerous infestation; be ready for a hostile burst along the route.'],{version:2,extraFiles:['lua_modules/constants/instance_versions.lua']});
add(82,'Survive the Hive Queen\'s waves, destroy her reflections and finish the final swarm.', ['Clear the staged hive defenders before committing to the queen.','At 75%, Sendaii splits into reflections. Eliminate the false images before driving the real queen to 45%.','At 45%, remaining images are absorbed and strengthen the queen.','At 25%, prepare for the swarm and preserve enough healing to finish.','Keep the final phase engaged; a prolonged loss of combat can reset it.'],{version:1,npc:[357016,357011],extraFiles:['lua_modules/constants/instance_versions.lua'],notes:['Curse strength depends on the character\'s curse progression. Full spell effects and live swarm balance have not been independently verified.']});
add(83,'Survive increasingly difficult rounds against I.R.A. and its clockwork reinforcements.', ['Face I.R.A. away from the raid; stand behind it to avoid Flamethrower.','Collect bashers, whirlygigs and repair clockworks as they enter.','Read the immunity label beneath each clockwork\'s name before choosing control; one enemy can have several immunities.','Use the respite between completed rounds to recover and prepare for stronger opponents.'],{version:1,npc:[450002,450003,450004,450005],extraFiles:['lua_modules/living_legacy.lua'],notes:['Marathon uses clockwork add waves; Sprint is documented separately.']});
add(84,'Push through I.R.A.\'s escalating rounds in a focused damage race.', ['Keep I.R.A. facing away from the raid and attack from behind to avoid Flamethrower.','Commit damage efficiently while keeping the tank stable through each stronger round.','Use each respite to recover quickly and prepare for the next round.'],{version:2,npc:[450002],extraFiles:['lua_modules/living_legacy.lua'],notes:['The current Sprint profile explicitly disables the clockwork add waves used in Marathon.']});
add('R003','A separate Fibblebrap mission selector loads a return to the mines.', ['Follow the active mission objectives through the mine.','The reviewed script gives Clicktok a peaceful quest-material exchange and a hostile response if hailed without it.','Keep the group ready before starting that conversation.'],{title:'Find Fibblebrap 5',version:2,npc:[367051],extraFiles:['lua_modules/constants/instance_versions.lua'],issues:['The version-2 loader selects find_fibblebrap_five, but that file repeats the Find Fibblebrap 1 header, task IDs and much of its objective logic. Fifth-mission identity and objective correctness remain unresolved; this is a provisional source-backed draft.']});
add('R006','Defeat the Cavern Creeper after Leklos falls to continue the raid.', ['Follow the chanting deeper into the cavern after defeating Leklos.','Tank the Cavern Creeper while the evokers perform their ritual.','Continue steady damage through the ritual announcements at 85%, 75% and 60%.'],{title:'The Cavern Creeper',version:2,npc:[259229],issues:['The health-stage handlers only emit dialogue and explicitly question whether additional effects are missing. No weakening, shield or timed vulnerability effect is claimed.']});
add(85,'Rhorious calls his lieutenants and groundpounders into the fight as his health drops.', ['At 75%, prepare to collect the named lieutenants.','At 50%, prepare for the groundpounders to join.','Defeat the battlemaster and all required supporting enemies to complete the event.','Keep the event engaged so its recovery and reset timers do not undo progress.']);
add(86,'Bloated Girplan rotates bile, breath and presence attacks.', ['Keep healing available for both Rain of Bile and Fetid Breath, each recurring once a minute after its initial cast.','Disconcerting Presence recurs every two minutes.','The combat timers stop on disengagement.'],{abilities:[{id:'spell-rotation',name:'Bile and breath',summary:'Three recurring casts pressure the group.',description:[],tags:['Recurring spells'],roles:[],spell_ids:[3764,6112,6113]}]});
add(87,'A necromancer quest releases three named creatures from the Discord Fluctuation.', ['The eligible necromancer activates the fluctuation through its proximity dialogue.','Prepare for Rargari, Gornogg and Arlagai to appear together.','Assign tanks before the trigger and focus the group on one opponent at a time.'],{npc:[336244,336243,336242]});
add(88,'The dark animist opens with five beasts and a recurring spell rotation.', ['Collect the five afflicted beasts immediately when the boss appears.','Prepare for Discordant Feedback and Corporeal Torment while controlling the animals.','Complete the fight within the thirty-minute combat window.'],{npc:[336248,336247,336249,336246,336245],notes:['The five participating add IDs are verified; the primary animist template ID still needs database or spawn-source confirmation.']});
add(89,'Three linked sharpshooters must be defeated as one encounter.', ['Engaging one sharpshooter can pull the other two into combat.','Each becomes mobile at 45% health, so prepare tanks to follow the change.','Finish all three; the first deaths remove their own loot while another sharpshooter remains.'],{npc:[336066,336067,336068]});
add(90,'Defeat Lhranc\'s minions before facing the returned shadow knight.', ['The eligible shadow knight completes Filligno\'s preparation and says ready to start.','The first minion leads into a pair; defeating the minions brings out Lhranc.','Prepare the tank for Harm Touch on engagement and recurring Defiled Insanity afterward.'],{npc:[336251,336250]});
for(const version of [0,200])add(91,'Lirah fights alongside protectors that can return during combat.', ['Assign add control before pulling the bridgekeeper.','Lirah repeatedly draws idle protectors into combat and checks for replacements.','Keep the boss tank stable while controlling renewed protectors.','A disengagement clears and rebuilds the supporting formation.'],{title:version?'Lirah the Bridgekeeper: Seasonal':'Lirah the Bridgekeeper',version,issues:['The replacement check looks for template 336129 but spawns 336130. Actual replacement timing and population need live verification.']});
add(92,'The Murkglider Breeder continually replenishes its spawn during combat.', ['Collect the first murkglider as the breeder is engaged.','Further spawn checks occur every twenty seconds while the breeder fights.','Keep the adds under control while maintaining damage on the breeder.']);
add(93,'Break Sverins\' control and subdue Uisima for the ranger rescue.', ['Prepare for linked acolytes and golem-bound spirits alongside the named enemies.','Keep healing ready for Sverins\' recurring Matter Dispersal.','Lower Uisima to 10% and allow the surrender condition to complete after the other threats are handled.','The eligible ranger should finish the conversation and quest hand-in after Uisima is freed.']);
add(94,'Tiorpat calls members of the surrounding crowd into combat.', ['Clear space and identify the surrounding dragorn before starting the confrontation.','Expect repeated calls for help while Tiorpat fights.','Collect newly hostile supporters promptly and keep them away from healers.','A prolonged disengagement can reset the gathering.']);
add(95,'Wren Simsy summons assassins, with more pressure when a larger group is nearby.', ['Prepare for two assassins as combat starts.','The opening participant check adds an assassin for each nearby player beyond four.','Finish the encounter inside the thirty-minute appearance window.','Wren\'s death removes the remaining shadowed assassins.']);
add(96,'Volklana begins rooted, casting terror until his health falls far enough.', ['Prepare for immediate Terror and further casts every five seconds while the boss remains above 85%.','At 85%, the terror timer stops and Volklana becomes mobile.','Have the tank ready to reposition for the mobile fight.','If his health recovers to 87%, he returns to his initial rooted position.'],{npc:[336141],abilities:[{id:'terror',name:'Zun\'Muram\'s Terror',summary:'Repeated casts affect clients within 120 units during the rooted opening.',description:[],tags:['Opening phase'],roles:[],spell_ids:[5821]}]});
add(97,'A beastlord quest calls the Girplan Spiritleech and a ring of spiritminions.', ['Have the group prepared before the quest hand-in to Yerika Sisslak.','The spawn sequence creates eleven spiritminions around the boss.','Collect the surrounding adds before they overwhelm the group and finish the spirit leech.'],{npc:[302085,302084],notes:['Current source contains eleven spiritminion spawns; the earlier audit summary understated the count.']});
add(98,'Seasonal Gorenaire pulses frost damage until her icy shell breaks.', ['Players within 60 units take the scripted frost pulse every ten seconds.','Keep ranged players outside that area when their abilities allow it and cover the melee group with healing.','At 15%, the pulse stops and the boss becomes more vulnerable to two-handed blunt and two-handed slashing attacks.'],{title:'Gorenaire: Seasonal',version:200,issues:['Health-phase comments label skills 2 and 3 incorrectly; guidance follows the skill numbers (two-handed blunt and two-handed slashing). The howl timer is commented out, so no recurring scripted howl is claimed.'],notes:['Only the version-200 custom mechanics are documented. The standard open-zone spawn does not run these combat timers.']});
add(99,'Defeat the screechers, control the bats and pursue Redfang through his disappearances.', ['Kill the seven opening screechers to bring out Redfang.','Control the recurring blooddrinkers while damaging the boss.','At 65% and 15%, Redfang disappears and the encounter shifts back to bat control.','Root the voracious bats when appropriate; the script recognizes root as a special response.','Keep the encounter moving to avoid the idle reset.'],{version:1,extraFiles:['lua_modules/constants/instance_versions.lua']});
add(100,'Drive Zi-Thuuli away through three encounters before the final confrontation.', ['Engage promptly when Zi-Thuuli appears; an idle appearance ends after fifteen seconds.','His first three encounters end at 55%, 50% and 45% health respectively.','Prepare for the recurring stone spell during longer engagements.','The next appearance after the third retreat is the killable finale.'],{version:1,npc:[351190],extraFiles:['lua_modules/constants/instance_versions.lua'],notes:['The script marks the ninety-second stone interval as an estimate. Full database spell behavior remains unverified.']});
add(101,'Quigli calls his crew when a monk accepts the challenge.', ['The eligible monk can choose the crew fight through dialogue.','The first crew arrives five seconds after the challenge begins.','Collect the lackey, swabbies and scallywag while keeping pressure on Quigli.','Finish inside the fifteen-minute encounter window.']);
add(102,'Protect Althele\'s druid gathering from the incoming dark elves.', ['Complete the gathering sequence before preparing for the attack.','About a minute after the ritual starts, a corruptor and two reavers advance toward Althele.','Intercept the attackers before they reach the druids.','Complete the quest follow-up before the gathering resets.'],{npc:[15044,15153,15150]});
add(103,'General Veronhar orders lethal arrow volleys while his commanders assist.', ['When the general orders the archers to ready their bows, duck before the five-second warning ends.','Keep supporting commanders controlled while maintaining the boss tank.','Fight inside the encounter area; pulling the enemies beyond its limits causes a return and cleansing response.']);
add(104,'Bloodeye calls two Ragepaw commanders at 75% health.', ['Have two adds covered when the boss reaches 75%.','Control Stonebite and Ironfur as they join the encounter.','Keep the fight in Bloodeye\'s area to avoid the out-of-bounds reset.'],{version:2,npc:[363017,363077,363076],extraFiles:['lua_modules/constants/instance_versions.lua']});
add(105,'Protect Boridain on his hunt and defeat the rabid kodiak at the end.', ['The quest hand-in starts Boridain\'s route.','Stay with him through his food and rest stops.','At the final stop, defeat the rabid tundra kodiak and return the requested proof to Boridain.'],{npc:[116597],notes:['The kodiak template is verified from its spawn call; Boridain\'s template ID is not independently resolved.']});
add(106,'Free Corbin and escort him through the orc and giant ambushes.', ['Prepare before the rescue hand-in starts the moving escort.','The first ambush brings Ry\'Gorr bashers directly onto the route.','The second brings Commander Bahreck and Kromrif soldiers. Stay close enough to protect Corbin.','Keep him alive until he reaches the final escape point.'],{npc:[116569,116591,116129]});
add(107,'Follow Icefang to Poxbreath and defeat the orc party.', ['Keep up when Icefang follows the scent.','Prepare for Poxbreath and nearby oracles at the destination.','Finish the confrontation promptly before Icefang\'s reset removes the event.'],{npc:[116596,116587]});
add(108,'Expose Peffin\'s protection and follow the confrontation through Berradin.', ['Have combat support ready before the quest exchange with Peffin.','Peffin\'s confrontation brings Kromrif elites; collect them before focusing the main target.','Complete Berradin\'s dialogue sequence and prepare for the replacement encounter form.'],{npc:[116605,116182],notes:['Both Peffin scripts are retained as reviewed source variants in the same standard-zone event. Their exact database spawn selection remains unverified.']});
add(109,'Escort Garadain into battle, defeat Chief Ry\'Gorr and bring him home alive.', ['Complete the marching-order hand-in only when the force is assembled.','Stay with Garadain as he gathers the Coldain and moves to the battlefield.','Prioritize protecting Garadain and defeating the chief amid the larger battle.','Return the required proof while the battle version of Garadain remains alive.']);
add(110,'Defend the Coldain camp against Scarbrow and his invading orcs.', ['The messenger-order hand-in to the lookout starts the assault.','Prepare to collect Scarbrow, invaders and oracles together.','Defeat Scarbrow and retain the required quest proof for Garadain.'],{npc:[116600,116586,116587]});
add(111,'Save the wounded Tain from Ghrek and the pursuing giants.', ['Prepare before telling Tain you will help.','Intercept Ghrek and four soldiers as they advance directly on Tain.','Defeat the leader and deliver the requested elixir to finish the rescue.'],{npc:[116604,116532]});
add(112,'Seasonal Severilous combines nearby poison bursts with random toxic gazes.', ['Players within 70 units take the scripted poison burst every fifteen seconds.','Be ready to heal the random player selected for Toxic Secretion every thirty-two seconds.','At 25%, the scripted timers stop and Severilous becomes more vulnerable to archery and backstab.'],{title:'Severilous: Seasonal',version:200,abilities:[{id:'toxic-gaze',name:'Toxic Secretion',summary:'A recurring gaze targets a random hated player.',description:[],tags:['Random target'],roles:[],spell_ids:[1117]}],issues:['Health-phase comments say slashing, but the implemented skill IDs 7 and 8 are archery and backstab. Guidance follows the implementation.'],notes:['Only the version-200 custom mechanics are documented. The standard open-zone spawn does not run these combat timers.']});
add(113,'Cazic Thule calls much of the Plane of Fear to defend him.', ['Clear the surrounding zone before engaging Cazic Thule.','The opening call adds most surviving zone NPCs to the top-threat target\'s hate list.','Keep spare tanks and control available for any enemies that arrive after the pull.'],{group:'Plane of Fear',notes:['Version-0 guidance covers the verified zone-assist script. The additional static-instance health phases are documented separately.']});
add(113,'Static-mode Cazic Thule combines zone reinforcements, fear and growing physical vulnerability.', ['Clear the zone before the pull; the initial call can bring surviving enemies to the main target.','Collect the nightmare minions summoned at 70% and 40%.','Prepare for fear casts at 60% and 30%.','Players within 60 units take a scripted terror pulse every forty seconds.','Slashing, two-handed blunt and one-handed piercing attacks gain increased effectiveness at 50%, with a larger vulnerability at 20%.'],{title:'Cazic Thule: Static Mode',version:255,group:'Plane of Fear',notes:['Several other health thresholds emit flavor announcements only. Damage guidance follows implemented skill IDs rather than swapped comments for skills 2 and 3.']});
add(114,'The static-mode dracoliche reassembles after nearly being defeated.', ['Cover nearby players for the necrotic breath pulse every twenty-five seconds.','Save enough resources for another push: at 1%, the dracoliche restores itself to 35% health.','Pick up the two fetid fiends that appear during reanimation.','A disengagement clears the adds and rearms the reanimation sequence.'],{title:'Dracoliche: Static Mode',version:255,issues:['The reanimation code toggles special ability 24 while its comments call that Unkillable. No guaranteed immunity is claimed; the three-second transition needs live verification.']});
add(115,'Dread and Fright use recurring Death Touch; all three golems can leave a broodling behind.', ['Have the pull and recovery plan ready before engaging Dread or Fright: the first Death Touch can occur almost immediately.','Further Death Touch casts repeat every forty-five seconds against the top-threat target.','A pet at the top of the hate list redirects the cast to its owner; the script also removes listed divine-aura protections.','After any golem dies, check for the possible iksar broodling.'],{notes:['Terror\'s reviewed script has the broodling branch but no scripted Death Touch loop; database spells were not reviewed.']});
add(116,'Qualifying kills can trigger a Fear-Touched Dracolich ambush.', ['During the associated active task, keep the group ready after each kill.','The ambush can appear at the slain enemy\'s location and immediately attack the credited player.','A tank should collect the dracolich before the group moves on.'],{npc:[72006],notes:['The loader is gated by the Rotten_Hand content flag; the spawn check requires task 17 and rolls a three-percent chance.']});
add(117,'The Ireblind Imp releases groups of rage essences at three health thresholds.', ['Prepare for three essences at each of 76%, 51% and 26%.','Collect and control the essences before pushing into the next threshold.','Keep the imp tank covered while damage dealers manage each new group.'],{npc:[72005],notes:['The essence add template is verified; the imp\'s template ID still needs independent confirmation.']});
add(118,'A druid\'s charmed alligator reveals the Swamp Terror.', ['Bring the required charmed alligator to the quest trigger with the group prepared.','The dialogue sequence ends with the Swamp Terror appearing nearby.','Have a tank ready to engage as soon as the creature emerges.'],{npc:[47208]});
add(119,'Hexxt Pzik Shziaak begins recurring ranged volleys below 45% health.', ['Prepare for a change in the combat pattern when the boss reaches 45%.','The volley check repeats every twenty seconds while that low-health behavior is active.','Keep healing stable and maintain tank control through the final push.']);
