for(const e of entries){let m=identity[e.id];if(m){e.npc=m[0];e.extraFiles=[...(e.extraFiles||[]),...(m[1]||[])];if(['E088','E117'].includes(e.id))e.notes=[];} }
function edit(id,values){for(const e of entries.filter(e=>e.id===id))Object.assign(e,values);}
function role(id,label,tips){return{id,label,tips};}
edit('E011',{
overview:['Defeat Vangl while killing the converts and removing Mark of Death before its delayed check. The scripted focus announcements do not themselves change his combat statistics.'],
tips:['Remove Mark of Death before its thirty-second check; a remaining mark triggers Cazic Touch.','Kill languished converts quickly because their damage grows over time.','Below 75%, subsequent mark cycles are shorter. At 10%, prepare for Feedback Dispersion.'],
phases:[phase('Opening','Above 75%','Control recurring converts and remove marks before they resolve.'),phase('Faster marks','Below 75%','The next mark scheduling uses a sixty-second cycle instead of seventy-five seconds.'),phase('Final pressure','10%','Vangl casts Feedback Dispersion. Finish while continuing the existing add and mark mechanics.')],
roles:[role('tank','Tanks',['Hold Vangl and collect each convert as it appears.']),role('support','Healers and support',['Arrange reliable mark removal before the thirty-second check.']),role('damage','Damage dealers',['Prioritize growing converts before returning to Vangl.'])],
notes:['The 75% and 50% health handlers otherwise provide dialogue and camera effects; no extra damage modifier is claimed.']});
edit('E012',{overview:['Split into three teams and keep the tormentors within five health percentage points of one another. Losing balance removes Jelvan\'s blessing and progressively enables additional attacks.'],tips:['Assign a tank and healing coverage to each tormentor.','Keep the highest and lowest tormentors less than six health percentage points apart to retain the blessing.','Health gaps of 11, 15 and 20 points enable additional spell timers. Correct the imbalance quickly.','Keep the fight inside the arena and avoid a prolonged loss of combat.'],roles:[role('tank','Tanks',['Hold one tormentor each inside the encounter area.']),role('damage','Damage dealers',['Shift damage to the highest-health tormentor to maintain balance.']),role('healer','Healers',['Expect more incoming spell pressure whenever the groups fall out of balance.'])]});
edit('E013',{overview:['Keep the pit-add kills flowing while a dedicated tank holds Keldovan. The recent-kill count weakens his defenses and abilities, but begins falling when kills stop.'],phases:[phase('Build the advantage','Initial engagement','Kill the pit adds to accumulate the weakening effect.'),phase('Maintain the advantage','Throughout combat','Continue add kills while damaging Keldovan; the recent-kill count decays after a gap.')],roles:[role('tank','Tanks',['Keep a separate tank on the pit adds.']),role('damage','Damage dealers',['Continue killing adds instead of abandoning them once the boss is weakened.'])]});
edit('E014',{overview:['Mata Muram requires fast personal reactions to his gaze, control of recurring adds, and a planned return after the raid is banished. Defeat Vangl before starting the initial dialogue.'],tips:['When personally warned of the gaze, obtain Reflective Skin before ten seconds pass.','A buzzing warning leads to five lashers at the selected player after six seconds; have add control ready.','At 70%, remove Mark of Death before its fifteen-second check.','After banishment, return through the encounter\'s intended route and use the boss dialogue to resume the fight.'],phases:[phase('Opening assault','Initial engagement','Control the coerced lieutenants and recurring lashers while responding to gaze warnings.'),phase('Mark of Death','70%','The boss applies marks to randomly selected clients and checks for remaining marks fifteen seconds later.'),phase('Converts','50%','Two languished converts appear. Collect and defeat them.'),phase('Riftseeker intervention','30%','Four riftseekers appear and restrain Mata Muram. Banishment follows after sixty seconds, or sooner if his health falls below 20%.'),phase('Return and finish','After banishment','The raid is moved away and Mata Muram retains his remaining health. Return correctly, reactivate him through dialogue and finish the encounter.')],npc:[317109,317114,317123,317117,317122],roles:[role('tank','Tanks',['Keep the boss and recurring enemies controlled through each transition.']),role('everyone','Everyone',['React immediately to personal gaze and buzzing warnings.']),role('support','Healers and support',['Prepare mark removal for the short fifteen-second resolution window.'])]});
edit('E015',{overview:['Ture alternates ordinary combat with a short area-rampage window. Move the melee group out on the warning, keep the main tank covered, then return when the rampage ends.'],phases:[phase('Combat','Between rampages','Maintain boss damage and heal through breath and destruction casts.'),phase('Rampage warning','Six-second warning','Move vulnerable melee players out of the area.'),phase('Area rampage','Ten seconds','Keep healing on the tank and wait for the rampage to end before moving back in.')]});
edit('E016',{overview:['Guard kills lower Hanvar\'s enforced health floor by five percentage points each. The raid needs twenty guard kills to remove the floor completely, while keeping the guards from sacrificing themselves.'],tips:['Kill guards promptly: each actual guard death lowers the protected health floor by five points.','A guard sacrifice casts Feedback Dispersion without advancing the kill count.','Continue until twenty guard kills remove the health floor, then finish Hanvar.','Keep the boss inside his encounter area and maintain healing through Chains and Wail of Anguish.'],phases:[phase('Protected warden','Health floor begins at 100%','Kill the five initial guards to begin lowering the floor.'),phase('Returning guards','Until twenty guard kills','Kill replacement guards before their sacrifice timer completes; each death lowers the floor by another five points.'),phase('Unprotected warden','Twenty guard kills','The floor reaches zero and the encounter stops requesting further replacements. Finish Hanvar.')],npc:[317002,317015,317016,317017,317018]});
